import json, glob, re
calls, fails = {}, []
for f in glob.glob('/home/username/.codex/sessions/**/*.jsonl', recursive=True):
    for line in open(f, errors='ignore'):
        try: p = (json.loads(line).get('payload') or {})
        except ValueError: continue
        if p.get('type') == 'custom_tool_call' and p.get('name') == 'exec':
            calls[p['call_id']] = re.findall(r'cmd:\s*"((?:[^"\\]|\\.)*)"', p.get('input') or '')
        elif p.get('type') == 'custom_tool_call_output':
            txt = ' '.join(b.get('text','') for b in (p.get('output') or []) if isinstance(b, dict))
            for label, code in re.findall(r'"label":"([^"]*)".*?"exit_code":(\d+)', txt):
                if code != '0': fails.append((f, p['call_id'], label, code, calls.get(p['call_id'])))
